static string Geometry(Mesh mesh){if(!mesh)return "null";var rows=new List<string>();var v=mesh.vertices;var n=mesh.normals;for(int sub=0;sub<mesh.subMeshCount;sub++){var t=mesh.GetTriangles(sub);for(int i=0;i<t.Length;i+=3){var keys=new string[3];for(int j=0;j<3;j++){int k=t[i+j];keys[j]=v[k].ToString("R")+(n.Length==v.Length?n[k].ToString("R"):"");}var cyc=new[]{keys[0]+keys[1]+keys[2],keys[1]+keys[2]+keys[0],keys[2]+keys[0]+keys[1]};Array.Sort(cyc,StringComparer.Ordinal);rows.Add(sub+":"+cyc[0]);}}rows.Sort(StringComparer.Ordinal);using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(string.Join("\n",rows))));}
