static void Preserve(Transform source,Transform candidate){if(source.name!=candidate.name||source.localPosition!=candidate.localPosition||source.localRotation!=candidate.localRotation||source.localScale!=candidate.localScale||source.gameObject.layer!=candidate.gameObject.layer||source.gameObject.tag!=candidate.gameObject.tag||source.gameObject.activeSelf!=candidate.gameObject.activeSelf)throw new Exception("Transform changed "+source.name);transforms++;var old=source.GetComponent<MeshFilter>();if(old){var next=candidate.GetComponent<MeshFilter>();if(!next||Geometry(old.sharedMesh)!=Geometry(next.sharedMesh))throw new Exception("Shape/normals changed "+source.name);meshes++;}var a=source.GetComponents<Collider>();var b=candidate.GetComponents<Collider>();if(a.Length!=b.Length)throw new Exception("Collider count changed "+source.name);for(int i=0;i<a.Length;i++){if(a[i].GetType()!=b[i].GetType()||Json(a[i])!=Json(b[i]))throw new Exception("Collider settings changed "+source.name);if(a[i] is MeshCollider ma&&b[i] is MeshCollider mb&&Geometry(ma.sharedMesh)!=Geometry(mb.sharedMesh))throw new Exception("Physics mesh changed");colliders++;}var ar=source.GetComponents<Rigidbody>();var br=candidate.GetComponents<Rigidbody>();if(ar.Length!=br.Length)throw new Exception("Rigidbody changed");for(int i=0;i<ar.Length;i++)if(Json(ar[i])!=Json(br[i]))throw new Exception("Rigidbody settings changed");if(candidate.childCount<source.childCount)throw new Exception("Existing children removed");for(int i=0;i<source.childCount;i++)Preserve(source.GetChild(i),candidate.GetChild(i));for(int i=source.childCount;i<candidate.childCount;i++)if(!candidate.GetChild(i).name.StartsWith("Formed inner rear bed jamb"))throw new Exception("Unexpected addition");}
static void Verify(GameObject candidate,string label){var source=Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(Source));source.name="rebirthCamper80s";candidate.name="rebirthCamper80s";transforms=meshes=colliders=0;Preserve(source.transform,candidate.transform);if(candidate.GetComponentsInChildren<Collider>(true).Length!=source.GetComponentsInChildren<Collider>(true).Length||candidate.GetComponentsInChildren<WheelCollider>(true).Length!=4)throw new Exception("Physical inventory changed");var originalFloor=source.GetComponentsInChildren<Renderer>(true).Single(r=>r.name=="Continuous pressed load floor - native tub cutouts");var floor=candidate.GetComponentsInChildren<Renderer>(true).Single(r=>r.name==originalFloor.name);if(floor.sharedMaterial.name!=originalFloor.sharedMaterial.name||floor.sharedMaterial.color!=originalFloor.sharedMaterial.color||floor.sharedMaterial.shader.name!=originalFloor.sharedMaterial.shader.name)throw new Exception("Black floor changed");log.AppendLine("PASS "+label+" existingTransforms="+transforms+" meshesExpandedTrianglePositionNormalSHA="+meshes+" colliders="+colliders+" fourWheels allsettingsunchanged; only2newvisualjambs, UV/materialdetailsallowed; blackfloorunchanged");Object.DestroyImmediate(source);log.AppendLine(RebirthPickupRearCornerRepair.Verify(candidate));}
